window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5aa14248c9da57f1"]={"versions": [{"id": "FIG-5aa14248c9da57f1", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Processing</code>) im Kontext des AUTOSAR Adaptive Platform Update and Configuration Management (UCM). Das Diagramm spezifiziert die Interaktion zwischen einer fahrzeugexternen oder -internen Diagnose-Applikation und dem UCM-Dienst zur Verarbeitung übertragener Software-Pakete.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagnostic Application (OEM specific)</strong>: Aktor / Client-Lebenslinie, fungiert als Service-Consumer.</li>\n<li><strong>:UCM</strong>: Service-Provider-Lebenslinie mit Stereotyp <code>«ServiceProvider»</code>.</li>\n<li><strong>Schnittstellen & Methoden / Events</strong>:</li>\n<li><code>Subscribe(CurrentStatus)</code>: Ereignis-Abonnement für Zustandsaktualisierungen.</li>\n<li><code>CurrentStatus= :IDLE</code>, <code>CurrentStatus= :BUSY</code>, <code>CurrentStatus= :READY</code>: Asynchrone Statusbenachrichtigungen des Feldes <code>CurrentStatus</code>.</li>\n<li><code>SetLogLevel(TransferId, LogLevel): GeneralResponseType</code>: Synchrone Methode zur Festlegung des Log-Levels mit Rückgabewert <code>:GeneralResponseType</code>.</li>\n<li><code>GetPackagesToProcess(SwInfoName): SwInfoVectorType</code>: Synchrone Abfrage zur Ermittlung verarbeitbarer Software-Pakete für einen gegebenen <code>SwInfoName</code>, liefert <code>:SwInfoVectorType</code>.</li>\n<li><code>ProcessSwPackage(TransferId): ProcessSwPackageReturnType</code>: Synchrone Anforderung zur Verarbeitung eines transferierten Pakets, liefert <code>:ProcessSwPackageReturnType</code>.</li>\n<li><code>GetProcessProgress(TransferId): uint8, ProcessingStatusType</code>: Synchrone Fortschrittsabfrage für eine <code>TransferId</code>, liefert Fortschrittswert (<code>uint8</code>) und Status (<code>ProcessingStatusType</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Diagnose-Applikation abonniert über <code>Subscribe(CurrentStatus)</code> das Status-Feld des UCM und empfängt die Initialmeldung <code>CurrentStatus= :IDLE</code>.</li>\n<li>In einem optionalen Block (<code>opt</code>) ruft die Applikation <code>SetLogLevel(TransferId, LogLevel)</code> auf und erhält die Antwort <code>:GeneralResponseType</code>.</li>\n<li>In einem weiteren optionalen Block (<code>opt</code>) ruft die Applikation <code>GetPackagesToProcess(SwInfoName)</code> auf und empfängt <code>:SwInfoVectorType</code>.</li>\n<li>Die Applikation startet die Verarbeitung über <code>ProcessSwPackage(TransferId)</code> und erhält synchron <code>:ProcessSwPackageReturnType</code>.</li>\n<li>Das UCM meldet über das abonnierte Feld den Zustandsübergang <code>CurrentStatus= :BUSY</code>.</li>\n<li>Innerhalb einer kontinuierlichen optionalen Schleife (<code>opt continously</code>) pollt die Applikation wiederholt mit <code>GetProcessProgress(TransferId)</code> und empfängt <code>:progress, ProcessingStatusType</code>.</li>\n<li>Nach Abschluss der Verarbeitung wechselt der Zustand auf <code>CurrentStatus= :READY</code>.</li>\n<li>Die Applikation fragt abschließend über <code>GetProcessProgress(TransferId)</code> das Endergebnis ab und erhält <code>:progress = 100, SUCCESS</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz verdeutlicht das Zusammenspiel aus ereignisbasierten Statusmeldungen (<code>CurrentStatus</code>) und synchronen Methodenaufrufen. Vor Aufruf von <code>ProcessSwPackage</code> muss das System im Zustand <code>IDLE</code> sein. Während der asynchronen Verarbeitung signalisiert <code>BUSY</code> die laufende Ausführung; der Fortschritt wird separat über Polling überwacht, bis der Zustand auf <code>READY</code> wechselt und der finale Erfolgsstatus abgefragt werden kann.</p>"}, {"id": "FIG-e47aa39e3cce76f0", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext des AUTOSAR Adaptive Platform Update and Configuration Management (UCM). Das Diagramm spezifiziert die Interaktion zwischen einer fahrzeugexternen oder -internen Diagnose-Applikation und einem generischen Dienstanbieter (<code>:External Reference</code>) zur Verarbeitung von Software-Paketen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagnostic Application (OEM specific)</strong>: Aktor / Client-Lebenslinie, fungiert als Service-Consumer.</li>\n<li><strong>:External Reference</strong>: Service-Provider-Lebenslinie mit Stereotyp <code>«ServiceProvider»</code>.</li>\n<li><strong>Schnittstellen & Methoden / Events</strong>:</li>\n<li><code>Subscribe(CurrentStatus)</code>: Ereignis-Abonnement für Zustandsaktualisierungen.</li>\n<li><code>CurrentStatus= :IDLE</code>, <code>CurrentStatus= :BUSY</code>, <code>CurrentStatus= :READY</code>: Asynchrone Statusbenachrichtigungen des Feldes <code>CurrentStatus</code>.</li>\n<li><code>SetLogLevel(TransferId, LogLevel)</code>: Methodenaufruf ohne modellierten Rückgabewert zur Festlegung des Log-Levels.</li>\n<li><code>GetSwPackages(): SwPackageInfoVectorType</code>: Parameterlose synchrone Methode zur Abfrage verfügbarer Software-Pakete, liefert <code>:SwPackageInfoVectorType</code>.</li>\n<li><code>ProcessSwPackage(TransferId): ProcessSwPackageReturnType</code>: Synchrone Anforderung zur Paketverarbeitung mit Rückgabewert <code>:ProcessSwPackageReturnType</code>.</li>\n<li><code>GetSwProcessProgress(TransferId): uint8</code>: Synchrone Fortschrittsabfrage für eine <code>TransferId</code>, liefert <code>:progress</code> (Typ <code>uint8</code>) bzw. im Erfolgsfall <code>:progress = 100, SUCCESS</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Diagnose-Applikation abonniert über <code>Subscribe(CurrentStatus)</code> das Status-Feld des Service-Providers und empfängt die Initialmeldung <code>CurrentStatus= :IDLE</code>.</li>\n<li>In einem optionalen Block (<code>opt</code>) ruft die Applikation <code>SetLogLevel(TransferId, LogLevel)</code> auf (ohne Rückgabewert-Nachricht).</li>\n<li>In einem weiteren optionalen Block (<code>opt</code>) fragt die Applikation mit <code>GetSwPackages()</code> die Paketliste ab und erhält <code>:SwPackageInfoVectorType</code>.</li>\n<li>Die Applikation stößt die Verarbeitung über <code>ProcessSwPackage(TransferId)</code> an und empfängt synchron <code>:ProcessSwPackageReturnType</code>.</li>\n<li>Der Service-Provider signalisiert die laufende Verarbeitung über die Benachrichtigung <code>CurrentStatus= :BUSY</code>.</li>\n<li>In einem kontinuierlichen optionalen Block (<code>opt continously</code>) pollt die Applikation mittels <code>GetSwProcessProgress(TransferId)</code> den Verarbeitungsfortschritt und empfängt <code>:progress</code>.</li>\n<li>Nach Beendigung meldet der Service-Provider <code>CurrentStatus= :READY</code>.</li>\n<li>Die Applikation verifiziert das Endergebnis über <code>GetSwProcessProgress(TransferId)</code> und empfängt <code>:progress = 100, SUCCESS</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Interaktion trennt die Zustandsüberwachung (<code>CurrentStatus</code>) von der detaillierten Fortschrittsüberwachung (<code>GetSwProcessProgress</code>). Das Starten von <code>ProcessSwPackage</code> bedingt den Vorzustand <code>IDLE</code>. Nach Anstoß wechselt die Entität in <code>BUSY</code>, bis mit Erreichen von <code>READY</code> und dem Abruf von <code>SUCCESS</code> der Übergang abgeschlossen ist.</p>"}, {"id": "FIG-42e73ff611dc40b5", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm im Kontext des AUTOSAR Adaptive Platform Update and Configuration Management (UCM). Das Diagramm spezifiziert die Interaktion zwischen einer fahrzeugexternen oder -internen Diagnose-Applikation und einem generischen Dienstanbieter (<code>:External Reference</code>) zur Verarbeitung von Software-Paketen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagnostic Application (OEM specific)</strong>: Aktor / Client-Lebenslinie, fungiert als Service-Consumer.</li>\n<li><strong>:External Reference</strong>: Service-Provider-Lebenslinie mit Stereotyp <code>«ServiceProvider»</code>.</li>\n<li><strong>Schnittstellen & Methoden / Events</strong>:</li>\n<li><code>Subscribe(CurrentStatus)</code>: Ereignis-Abonnement für Zustandsaktualisierungen.</li>\n<li><code>CurrentStatus= :IDLE</code>, <code>CurrentStatus= :PROCESSING</code>, <code>CurrentStatus= :READY</code>: Asynchrone Statusbenachrichtigungen des Feldes <code>CurrentStatus</code>.</li>\n<li><code>SetLogLevel(TransferId, LogLevel)</code>: Methodenaufruf ohne modellierten Rückgabewert zur Festlegung des Log-Levels.</li>\n<li><code>GetSwPackages(): SwPackageInfoVectorType</code>: Parameterlose synchrone Methode zur Abfrage verfügbarer Software-Pakete, liefert <code>:SwPackageInfoVectorType</code>.</li>\n<li><code>ProcessSwPackage(TransferId): ProcessSwPackageReturnType</code>: Synchrone Anforderung zur Paketverarbeitung mit Rückgabewert <code>:ProcessSwPackageReturnType</code>.</li>\n<li><code>GetSwProcessProgress(TransferId): uint8</code>: Synchrone Fortschrittsabfrage für eine <code>TransferId</code>, liefert <code>:progress</code> (Typ <code>uint8</code>) bzw. im Erfolgsfall <code>:progress = 100, SUCCESS</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Diagnose-Applikation abonniert über <code>Subscribe(CurrentStatus)</code> das Status-Feld des Service-Providers und empfängt die Initialmeldung <code>CurrentStatus= :IDLE</code>.</li>\n<li>In einem optionalen Block (<code>opt</code>) ruft die Applikation <code>SetLogLevel(TransferId, LogLevel)</code> auf (ohne Rückgabewert-Nachricht).</li>\n<li>In einem weiteren optionalen Block (<code>opt</code>) fragt die Applikation mit <code>GetSwPackages()</code> die Paketliste ab und erhält <code>:SwPackageInfoVectorType</code>.</li>\n<li>Die Applikation stößt die Verarbeitung über <code>ProcessSwPackage(TransferId)</code> an und empfängt synchron <code>:ProcessSwPackageReturnType</code>.</li>\n<li>Der Service-Provider signalisiert die laufende Verarbeitung über die Benachrichtigung <code>CurrentStatus= :PROCESSING</code>.</li>\n<li>In einem kontinuierlichen optionalen Block (<code>opt continously</code>) pollt die Applikation mittels <code>GetSwProcessProgress(TransferId)</code> den Verarbeitungsfortschritt und empfängt <code>:progress</code>.</li>\n<li>Nach Beendigung meldet der Service-Provider <code>CurrentStatus= :READY</code>.</li>\n<li>Die Applikation verifiziert das Endergebnis über <code>GetSwProcessProgress(TransferId)</code> und empfängt <code>:progress = 100, SUCCESS</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Interaktion trennt die Zustandsüberwachung (<code>CurrentStatus</code>) von der detaillierten Fortschrittsüberwachung (<code>GetSwProcessProgress</code>). Das Starten von <code>ProcessSwPackage</code> bedingt den Vorzustand <code>IDLE</code>. Nach Anstoß wechselt die Entität in <code>PROCESSING</code>, bis mit Erreichen von <code>READY</code> und dem Abruf von <code>SUCCESS</code> der Übergang abgeschlossen ist.</p>"}], "trans": [{"from": "FIG-5aa14248c9da57f1", "to": "FIG-e47aa39e3cce76f0", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Der äußere Sequenzdiagramm-Rahmen <code>sd Processing</code> entfällt.</li>\n<li>Der Service-Provider wird von <code>:UCM</code> zu <code>:External Reference</code> umbenannt.</li>\n<li>Der synchrone Rückgabepfad von <code>SetLogLevel(TransferId, LogLevel): GeneralResponseType</code> mit <code>:GeneralResponseType</code> entfällt; <code>SetLogLevel(TransferId, LogLevel)</code> wird nun ohne explizite Rückgabe modelliert.</li>\n<li>Methodenaufruf <code>GetPackagesToProcess(SwInfoName): SwInfoVectorType</code> mit Rückgabe <code>:SwInfoVectorType</code> wird ersetzt durch parameterloses <code>GetSwPackages(): SwPackageInfoVectorType</code> mit Rückgabe <code>:SwPackageInfoVectorType</code>.</li>\n<li>Methodenaufruf <code>GetProcessProgress(TransferId): uint8, ProcessingStatusType</code> mit Rückgabe <code>:progress, ProcessingStatusType</code> bzw. <code>:progress = 100, SUCCESS</code> wird ersetzt durch <code>GetSwProcessProgress(TransferId): uint8</code> mit Rückgabe <code>:progress</code> bzw. <code>:progress = 100, SUCCESS</code>.</li>\n</ul>"}, {"from": "FIG-e47aa39e3cce76f0", "to": "FIG-42e73ff611dc40b5", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Die Statusbenachrichtigung nach Aufruf von <code>ProcessSwPackage</code> ändert sich von <code>CurrentStatus= :BUSY</code> zu <code>CurrentStatus= :PROCESSING</code>.</li>\n</ul>"}]};
